import numpy as np
import os

BASE_DIR = "/root/autodl-tmp/distrib_canary_collapse/results/alpha_sweep"
METRICS = ["token_entropy", "ece", "distinct_1", "distinct_2", "distinct_3", "mauve"]

def load_metrics(exp_dir):
    path = os.path.join(BASE_DIR, exp_dir, "all_metrics.json")
    if not os.path.exists(path):
        return None
    with open(path) as f:
        return json.load(f)

# Load baseline
baseline = load_metrics("a000_s42_fp32")
n_gens = len(baseline)

# Method 1: deviation from own gen0, threshold = 2σ of null's deviations from null's gen0
# This is what v1 did - but it's too lenient because null gen0->gen1 is already large
null_gen0 = {m: baseline[0][m] for m in METRICS}
null_devs = {m: [abs(baseline[g][m] - null_gen0[m]) for g in range(1, n_gens)] for m in METRICS}
method1_sigma = {m: float(np.std(null_devs[m])) for m in METRICS}
method1_thresh = {m: 2 * method1_sigma[m] for m in METRICS}

# Method 2: Compare treatment trajectory to null trajectory at same generation
# onset = first t where |treatment(t) - null(t)| > 2σ_null_temporal
# σ_null_temporal = std of null values across generations
null_vals = {m: [baseline[g][m] for g in range(n_gens)] for m in METRICS}
null_mean = {m: float(np.mean(null_vals[m])) for m in METRICS}
null_std = {m: float(np.std(null_vals[m])) for m in METRICS}
method2_thresh = {m: 2 * null_std[m] for m in METRICS}

# Method 3: Relative change from gen0 compared to null's relative change from gen0
# onset = first t where |pct_change_treatment(t) - pct_change_null(t)| > threshold
# This normalizes out the gen-1 artifact
null_pct_change = {m: [] for m in METRICS}
for g in range(1, n_gens):
    for m in METRICS:
        if abs(null_gen0[m]) > 1e-10:
            null_pct_change[m].append((baseline[g][m] - null_gen0[m]) / abs(null_gen0[m]))
        else:
            null_pct_change[m].append(0)
null_pct_std = {m: float(np.std(null_pct_change[m])) for m in METRICS}
method3_thresh = {m: 2 * null_pct_std[m] for m in METRICS}

def compute_onset_method2(exp_dir):
    """Compare treatment(t) vs null(t) at same generation."""
    data = load_metrics(exp_dir)
    if data is None:
        return None
    onset = {}
    for m in METRICS:
        onset[m] = None
        for g in range(1, min(n_gens, len(data))):
            diff = abs(data[g][m] - baseline[g][m])
            if diff > method2_thresh[m]:
                onset[m] = g
                break
    return onset

def compute_onset_method3(exp_dir):
    """Compare relative changes, normalizing out gen-1 artifact."""
    data = load_metrics(exp_dir)
    if data is None:
        return None
    gen0 = data[0]
    onset = {}
    for m in METRICS:
        onset[m] = None
        for g in range(1, min(n_gens, len(data))):
            if abs(gen0[m]) > 1e-10:
                treat_pct = (data[g][m] - gen0[m]) / abs(gen0[m])
            else:
                treat_pct = 0
            null_pct = null_pct_change[m][g-1]
            if abs(treat_pct - null_pct) > method3_thresh[m]:
                onset[m] = g
                break
    return onset
